function booksStrip(){if(demo)return '';const problems=state.accounts.filter(a=>accountFilter==='all'||a.id===accountFilter).map(a=>accountBooks(state,a.id)).filter(b=>b.status==='attention');if(!problems.length)return '';const gaps=problems.reduce((v,b)=>v+b.gaps.length,0),other=problems.reduce((v,b)=>v+b.issues-b.gaps.length,0);return `<div class="review-strip books-strip"><div class="review-icon">${icon('alert',18)}</div><div><b>Your books have gaps to close.</b><p>${[gaps?`${gaps} missing statement period${gaps>1?'s':''}`:'',other?`${other} balance difference${other>1?'s':''}`:''].filter(Boolean).join(' · ')} across ${problems.length} account${problems.length>1?'s':''}. Reports may be incomplete until these are fixed.</p></div><button class="btn" data-page="statements">Check statements ${icon('chevron',12)}</button></div>`}
