 const ids=pairs.map(p=>[p.debit.id,p.credit.id]),options=choices.map(g=>g.options.map(o=>[o.debit.id,o.credit.id])),leg=t=>`${esc(transactionLabel(t).title)}<small class="pair-narration">${esc(t.description)}</small>`;
 const pairList=pairs.length?`<div class="pair-list">${pairs.map((p,i)=>`<label class="pair-row"><input type="checkbox" data-pair="${i}" checked><span><b>${money(-p.debit.amount)}</b> · ${esc(p.debit.account)} → ${esc(p.credit.account)}<small>${fmtDate(p.debit.date)}${p.debit.date!==p.credit.date?' → '+fmtDate(p.credit.date):''} · ${esc(p.reason)}</small><small>${esc(transactionLabel(p.debit).title)} / ${esc(transactionLabel(p.credit).title)}</small></span></label>`).join('')}</div>`:'';
 const choiceList=choices.length?`<h3 class="pair-heading">Pick the other side</h3><p class="sub">These have more than one equally likely match. Choose the right one, or leave them for later.</p>${choices.map((g,i)=>`<fieldset class="pair-choice"><legend><b>${money(Math.abs(g.anchor.amount))}</b> ${g.anchor.amount>0?'into':'out of'} ${esc(g.anchor.account)} · ${fmtDate(g.anchor.date)} · ${leg(g.anchor)}</legend>${g.options.map((o,j)=>`<label class="pair-row"><input type="radio" name="pair-choice-${i}" data-choice="${i}" value="${j}"><span>${g.anchor.amount>0?'From':'To'} ${esc(o.other.account)} · ${fmtDate(o.other.date)} · ${esc(o.reason)}<small>${leg(o.other)}</small></span></label>`).join('')}<label class="pair-row"><input type="radio" name="pair-choice-${i}" data-choice="${i}" value="" checked><span>Decide later</span></label></fieldset>`).join('')}`:'';
