 const selected=()=>[...[...document.querySelectorAll('[data-pair]:checked')].map(el=>ids[+el.dataset.pair]),...[...document.querySelectorAll('[data-choice]:checked')].filter(el=>el.value!=='').map(el=>options[+el.dataset.choice][+el.value])];
