function securityStrip(){return viewer&&viewer.twoFactorEnabled===false&&!demo?`<div class="review-strip security-strip"><div class="review-icon">${icon('shield',18)}</div><div><b>Protect your ledger with two-step verification.</b><p>Your bank statements are behind a password only. Add a code from your phone so a leaked password is not enough.</p></div><a class="btn" href="/security">Turn it on ${icon('chevron',12)}</a></div>`:''}
