function bind(){preferencesUI.bind();pwaUI.bind();categoryUI.bind();inviteUI.bind();bankUI.bind();investmentUI.bind();transactionUI.bind(refreshBulk);refreshBulk();document.querySelectorAll('[data-not-recurring]').forEach(el=>el.onclick=async e=>{e.stopPropagation();const key=el.dataset.notRecurring,payee=el.dataset.payee;state.recurringDismissed=[...(state.recurringDismissed||[]).filter(d=>d.key!==key),{key,payee:payee.slice(0,160),at:new Date().toISOString()}];if(await save('Marked as not recurring')){render();toast(`${payee} is no longer treated as a recurring payment`);}});document.querySelectorAll('[data-receipt]').forEach(el=>el.onclick=e=>{e.stopPropagation();captureUI.viewReceipts(el.dataset.receipt)});document.querySelectorAll('[data-statement-details]').forEach(el=>el.onclick=()=>statementDetails(el.dataset.statementDetails));document.querySelectorAll('[data-recurring]').forEach(el=>el.onclick=()=>{if(!leaveWorkspace())return;page='transactions';search=el.dataset.recurring;typeFilter='all';reviewFilter=false;resetList();render()});document.querySelectorAll('[data-apply-rule]').forEach(el=>el.onclick=async()=>{const rule=state.rules[+el.dataset.applyRule];if(!rule)return;const n=applyRule(rule);if(await save(`Rule applied to ${n} transactions`)){render();toast(`${n} transactions updated by “${rule.keyword}”`)}});if($('#account-filter'))$('#account-filter').onchange=e=>{if(!leaveWorkspace()){e.target.value=accountFilter;return;}accountFilter=e.target.value;resetList();render()};document.querySelectorAll('[data-page]').forEach(el=>el.onclick=e=>{if(el.tagName==='A'&&(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button!==0))return;e.preventDefault();navigate(el.dataset.page)});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));if($('#period'))$('#period').onchange=e=>{if(!leaveWorkspace()){e.target.value=period;return;}period=e.target.value;resetList();render()};if($('#search'))$('#search').oninput=e=>{if(!leaveWorkspace()){e.target.value=search;return;}search=e.target.value;resetList();showResults();};if($('#sort'))$('#sort').onchange=e=>{if(!leaveWorkspace()){e.target.value=sortBy;return;}setSort(e.target.value);render()};if($('#category-filter'))$('#category-filter').onchange=e=>{if(!leaveWorkspace()){e.target.value=categoryFilter;return;}categoryFilter=e.target.value;resetList();render()};if($('#tag-filter'))$('#tag-filter').onchange=e=>{if(!leaveWorkspace()){e.target.value=tagFilter;return;}tagFilter=e.target.value;resetList();render()};if($('#type-filter'))$('#type-filter').onchange=e=>{if(!leaveWorkspace()){e.target.value=typeFilter;return;}typeFilter=e.target.value;resetList();render()};if($('#rule-form'))$('#rule-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),rule={keyword:f.get('keyword').trim(),category:f.get('category')};if(!rule.keyword){toast('Enter a word to match.');return}state.rules.push(rule);const n=f.get('backfill')?applyRule(rule):0;if(await save(n?`Category rule added; ${n} transactions updated`:'Category rule added')){render();toast(n?`Rule saved · ${n} existing transactions updated`:'Rule saved for future imports')}};document.querySelectorAll('[data-remove-rule]').forEach(el=>el.onclick=async()=>{state.rules.splice(+el.dataset.removeRule,1);if(await save('Category rule removed'))render()});document.querySelectorAll('[data-attach-statement]').forEach(el=>el.onclick=()=>attachOriginal(el.dataset.attachStatement));document.querySelectorAll('[data-delete-statement]').forEach(el=>el.onclick=()=>removeStatement(el.dataset.deleteStatement));}
function bindModal(){document.querySelectorAll('#modal [data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action))}
async function action(a){const wasEditing=transactionUI.isEditing();if(a!=='close'&&!transactionUI.leave())return;if(a!=='close'&&wasEditing)render();if(a==='refresh')refresh(true);if(a==='migrate')migrateLocal();if(a==='upload')upload();if(a==='close')$('#modal').close();if(a==='empty-start'){demo=false;state.initialized=true;if(await save('Workspace initialized'))render()}if(a==='review'){page='transactions';reviewFilter=true;search='';typeFilter='all';tagFilter='all';categoryFilter='all';dayFilter='';resetList();render()}if(a==='review-income'){page='transactions';reviewFilter=false;search='';typeFilter='Income';tagFilter='all';categoryFilter='all';dayFilter='';resetList();render()}if(a==='tags')manageTags();if(a==='clear-day'){dayFilter='';resetList();render()}if(a==='review-toggle'){reviewFilter=!reviewFilter;resetList();render()}if(a==='more'){pageLimit+=200;showResults()}if(a==='tax-export')taxExport();if(a==='pair-transfers')pairTransfers();if(a==='export')download(csvExport(page==='transactions'?filtered():rows(),(index=>({category:t=>catLabel(t.category),tax_tag:t=>taxTagFor(t)?.label||'',linked_account:t=>partnerOf(t,index)?.account||'',tags:t=>(t.tags||[]).join(', ')}))(transferIndex(state.transactions)),state.titleRules||[]),`ledger-${period}.csv`,'text/csv;charset=utf-8');if(a==='template')download('Date,Description,Debit,Credit\n01/10/2026,Salary,,100000.00\n02/10/2026,Groceries,2500.00,\n','ledger-template.csv','text/csv');if(a==='print')window.print();if(a==='settings')settings();if(a==='nav-more')morePages();if(a==='customize-dashboard')customize('dashboard');if(a==='customize-reports')customize('reports');if(a==='recurring-hidden')recurringHidden();if(a==='capture')captureUI.open();}
